 ]},
 {"clause_id": "c045", "issues": []},
 {"clause_id": "c046", "issues": []},
 {"clause_id": "c047", "issues": []},
 {"clause_id": "c048", "issues": [
   {"issue": "\"Servicer Information\" is confined to information \"contained under the heading 'The Servicer'\" in the Offering Document, so servicer-related disclosure appearing under any other caption falls outside both the Section 2.04(e) representation and the Section 2.01(m) carve-out. The caption-based boundary is the whole of the definition.", "type": 1, "prob": 0.12}
 ]},
 {"clause_id": "c049", "issues": []},
 {"clause_id": "c050", "issues": [
